&quot;) else: print(&quot;非訊息事件&quot;) 注意縮排 完整程式碼line_bot&#x2F;views.py123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105from django.shortcuts import renderfrom django.http import HttpResponse, HttpResponseBadRequest, HttpResponseForbiddenfrom django.views.decorators.csrf import csrf_exemptfrom django.conf import settingsfrom linebot import LineBotApi, WebhookParserfrom linebot.exceptions import InvalidSignatureError, LineBotApiErrorfrom linebot.models import MessageEvent, TextMessage, TextSendMessage, LocationMessagefrom linebot.models import StickerMessage, StickerSendMessagefrom linebot.models import ImageMessage, ImageSendMessage# Create your views here.line_bot_api = LineBotApi(settings.LINE_CHANNEL_TOKEN)parser = WebhookParser(settings.LINE_CHANNEL_SERCRET)@csrf_exemptdef callback(request): if (request.method == &quot;POST&quot;): signature = request.META[&#x27;HTTP_X_LINE_SIGNATURE&#x27;] body = request.body.decode(&#x27;utf-8&#x27;) # 資料驗證: 是否來自 lINE 伺服器 try: events = parser.parse(body, signature) except InvalidSignatureError: return HttpResponseForbidden() except LineBotApiError: return HttpResponseBadRequest() for event in events: print(&quot;收到訊息&quot;, event, &quot;
&quot;) if isinstance(event, MessageEvent): if isinstance(event.message, TextMessage): print(&quot;收到訊息:&quot;, event.message.text, &quot;
&quot;) if event.message.text == &quot;###我要報到###&quot;: line_bot_api.reply_message( event.reply_token, TextSendMessage(text=&quot;報到成功!!!&quot;) ) elif event.message.text == &quot;###我的名牌###&quot;: line_bot_api.reply_message( event.reply_token, TextSendMessage(text=&quot;您的編號是 001 !&quot;) ) elif event.message.text == &quot;###車牌登入###&quot;: line_bot_api.reply_message( event.reply_token, TextSendMessage(text=&quot;ABC-123 登入成功&quot;) ) elif event.message.text == &quot;Test&quot;: line_bot_api.reply_message( event.reply_token, TextSendMessage(text=&quot;&#123;&#125;media/&#123;&#125;&quot;.format(request.build_absolute_uri(&#x27;/&#x27;), &quot;123.jpg&quot;)) ) else: line_bot_api.reply_message( event.reply_token, TextSendMessage(text=&quot;目前尚未開放詢問喔&quot;) ) elif isinstance(event.message, LocationMessage): print(&quot;收到定位訊息:&quot;, event) line_bot_api.reply_message( event.reply_token, TextSendMessage(text=&quot;緯度:&#123;&#125;, 經度:&#123;&#125;&quot;.format(event.message.latitude, event.message.longitude)) ) elif isinstance(event.message, StickerMessage): print(&quot;收到貼圖&quot;, event.message) line_bot_api.reply_message( event.reply_token, StickerSendMessage( 8525, 16581290, ) ) elif isinstance(event.message, ImageMessage): print(&quot;收到圖片&quot;, event.message) image_name = event.message.id + &quot;.jpg&quot; image_content = line_bot_api.get_message_content(event.message.id) path = &quot;./public/uploads/&quot; + image_name with open(path, &#x27;wb&#x27;) as fd: for chunk in image_content.iter_content(): fd.write(chunk) reply_image_path = &quot;https://&#123;&#125;/media/&#123;&#125;&quot;.format(request.get_host(), image_name) line_bot_api.reply_message( event.reply_token, ImageSendMessage( preview_image_url=reply_image_path, original_content_url=reply_image_path, ) ) else: print(&quot;文字以外的類型
&quot;) else: print(&quot;非訊息事件&quot;) return HttpResponse() EP47 EP48 EP49

